@startuml

class Traveller {
  +name: string
  +companyName: string
  +address: string
  +travelPreferences: string[]
  +reliabilityRating: float
}

class SearchCriteria {
  +city: string
  +arrivalDate: date
  +departureDate: date
  +numberOfRooms: int
  +roomType: string
  +minimumHotelRating: int
  +maxCostPerNight: float
  +furtherPreferences: string[]
}

class PreliminaryBooking {
  +bookingIdentifier: string
  +price: float
  +cityArea: string
  +hotelRating: int
  +keyPreferences: string[]
}

class Booking {
  +creditCardInformation: string
  +cancellationDeadline: date
  +isConfirmed: boolean
}

class SpecialOffer {
  +price: float
}

class Hotel {
  +name: string
  +address: string
  +city: string
  +rating: int
}

class HotelChain {
  +name: string
}

class RoomType {
  +typeName: string
}

class Availability {
  +isFullyBooked: boolean
}

class HBMS {
  +calculateReliabilityRating(traveller: Traveller)
}

Traveller "1" -- "*" PreliminaryBooking : creates
Traveller "1" -- "*" Booking : completes
Traveller "1" -- "*" SpecialOffer : receives
Traveller "1" -- "*" Booking : provides credit card for

HBMS "1" -- "*" PreliminaryBooking : manages
HBMS "1" -- "*" Booking : manages
HBMS "1" -- "*" SpecialOffer : sends
HBMS "1" -- "*" Hotel : lists
HBMS "1" -- "*" Traveller : stores information for

Hotel "0..1" -- "1" HotelChain : run by
Hotel "1" -- "*" RoomType : announces
Hotel "1" -- "*" Availability : manages
Hotel "1" -- "*" Booking : confirms
Hotel "1" -- "1" Address : located at

Booking <|-- PrePaidBooking
Booking <|-- PaidAtHotelBooking

class PrePaidBooking
class PaidAtHotelBooking

"1" -- "0..*" PreliminaryBooking : forwarded to
"1" -- "*" SpecialOffer : provided by competitor hotels
"1" -- "1" Booking : can be switched to

@enduml

